begin;
create extension if not exists pgtap with schema extensions;
select plan(49);

update public.bookings set status = 'expired'
where status in ('held', 'confirmed') and start_at > now();

insert into auth.users (id, aud, role, phone, phone_confirmed_at, raw_user_meta_data, raw_app_meta_data)
values
  ('11111111-1111-4111-8111-111111111111', 'authenticated', 'authenticated', '+919444444401', now(), '{}', '{}'),
  ('22222222-2222-4222-8222-222222222222', 'authenticated', 'authenticated', '+919444444402', now(), '{}', '{}'),
  ('33333333-3333-4333-8333-333333333333', 'authenticated', 'authenticated', '+919444444403', now(), '{}', '{}');
update public.profiles set role = 'admin' where id = '11111111-1111-4111-8111-111111111111';
update public.profiles set role = 'counselor' where id = '22222222-2222-4222-8222-222222222222';
set local role authenticated;
select set_config('request.jwt.claim.sub', '11111111-1111-4111-8111-111111111111', true);
insert into public.counselors (id, profile_id, display_name, bio, qualifications, experience, specialties, languages, photo_url, published)
values ('44444444-4444-4444-8444-444444444444', '22222222-2222-4222-8222-222222222222', 'Availability Test', 'Bio', 'Degree', 'Experience', 'Specialty', 'English', 'https://example.test/photo.jpg', true);
select lives_ok($$select public.set_availability_settings(45, 15, 60, 10)$$, 'admin can set scheduling rules');
select set_config('request.jwt.claim.sub', '22222222-2222-4222-8222-222222222222', true);
select lives_ok($$select public.save_availability_rule('44444444-4444-4444-8444-444444444444', null, 3, '10:00', '13:00')$$, 'counselor can add own weekly hours');
select lives_ok($$select public.save_availability_exception('44444444-4444-4444-8444-444444444444', null, '2031-01-01', 'blocked', false, '11:30', '12:00')$$, 'counselor can block a period');
select lives_ok($$select public.save_availability_rule('44444444-4444-4444-8444-444444444444', (select id from public.availability_rules where counselor_id = '44444444-4444-4444-8444-444444444444'), 3, '09:00', '13:00')$$, 'counselor can edit weekly hours');
reset role;
select ok(exists (select 1 from public.calculate_availability_slots('44444444-4444-4444-8444-444444444444', '2031-01-01 02:30+00') where start_at = '2031-01-01 03:30+00'), 'editing weekly hours changes generated slots');
set local role authenticated;
select lives_ok($$select public.save_availability_rule('44444444-4444-4444-8444-444444444444', (select id from public.availability_rules where counselor_id = '44444444-4444-4444-8444-444444444444'), 3, '10:00', '13:00')$$, 'weekly hours can be restored');
select lives_ok($$select public.save_availability_exception('44444444-4444-4444-8444-444444444444', (select id from public.availability_exceptions where counselor_id = '44444444-4444-4444-8444-444444444444' and local_date = '2031-01-01' and kind = 'blocked'), '2031-01-01', 'blocked', false, '10:30', '11:00')$$, 'counselor can edit a block');
reset role;
select ok(not exists (select 1 from public.calculate_availability_slots('44444444-4444-4444-8444-444444444444', '2031-01-01 03:30+00') where start_at = '2031-01-01 04:30+00'), 'editing a block removes the newly blocked slot');
set local role authenticated;
select lives_ok($$select public.save_availability_exception('44444444-4444-4444-8444-444444444444', (select id from public.availability_exceptions where counselor_id = '44444444-4444-4444-8444-444444444444' and local_date = '2031-01-01' and kind = 'blocked'), '2031-01-01', 'blocked', false, '11:30', '12:00')$$, 'blocked period can be restored');
reset role;
select ok(exists (select 1 from public.calculate_availability_slots('44444444-4444-4444-8444-444444444444', '2031-01-01 03:29:59+00') where start_at = '2031-01-01 04:30+00'), 'slot just before the minimum notice cutoff is visible');
select ok(not exists (select 1 from public.calculate_availability_slots('44444444-4444-4444-8444-444444444444', '2031-01-01 03:30:01+00') where start_at = '2031-01-01 04:30+00'), 'slot just after the minimum notice cutoff is hidden');
set local role authenticated;
select lives_ok($$select public.save_availability_exception('44444444-4444-4444-8444-444444444444', null, '2031-01-11', 'opening', false, '10:00', '11:00')$$, 'counselor can add an opening at the advance limit');
reset role;
select ok(not exists (select 1 from public.calculate_availability_slots('44444444-4444-4444-8444-444444444444', '2031-01-01 04:29:59+00') where start_at = '2031-01-11 04:30+00'), 'slot just outside the maximum advance is hidden');
select ok(exists (select 1 from public.calculate_availability_slots('44444444-4444-4444-8444-444444444444', '2031-01-01 04:30+00') where start_at = '2031-01-11 04:30+00'), 'slot exactly at the maximum advance is visible');
select ok(exists (select 1 from public.calculate_availability_slots('44444444-4444-4444-8444-444444444444', '2031-01-01 04:30:01+00') where start_at = '2031-01-11 04:30+00'), 'slot just inside the maximum advance is visible');
set local role authenticated;
select lives_ok($$select public.delete_availability('44444444-4444-4444-8444-444444444444', (select id from public.availability_exceptions where counselor_id = '44444444-4444-4444-8444-444444444444' and local_date = '2031-01-11'), 'exception')$$, 'counselor can delete a date-specific opening');
reset role;
select ok(not exists (select 1 from public.calculate_availability_slots('44444444-4444-4444-8444-444444444444', '2031-01-01 04:30+00') where start_at = '2031-01-11 04:30+00'), 'deleting an opening removes its slot');
set local role authenticated;
select throws_ok($$select public.save_availability_rule('44444444-4444-4444-8444-444444444444', null, 7, '10:00', '13:00')$$, '23514', null, 'weekday outside the valid range is rejected');
select throws_ok($$select public.save_availability_exception('44444444-4444-4444-8444-444444444444', null, '2031-01-02', 'opening', true, null, null)$$, '23514', null, 'an all-day opening is rejected');
select throws_ok($$select public.save_availability_exception('44444444-4444-4444-8444-444444444444', null, '2031-01-02', 'blocked', false, '12:00', '10:00')$$, '23514', null, 'a reversed date-specific time range is rejected');
select throws_ok($$select public.delete_availability('44444444-4444-4444-8444-444444444444', '55555555-5555-4555-8555-555555555555', 'unknown')$$, '22023', 'Invalid availability kind', 'an invalid deletion kind is rejected');
select throws_ok($$select public.set_availability_settings(45, 15, 60, 10)$$, '42501', 'Administrator required', 'counselor cannot change settings');
select set_config('request.jwt.claim.sub', '33333333-3333-4333-8333-333333333333', true);
select throws_ok($$select public.save_availability_rule('44444444-4444-4444-8444-444444444444', null, 3, '10:00', '13:00')$$, '42501', 'Not authorized', 'customer cannot change availability');
select ok(not has_table_privilege('authenticated', 'public.availability_rules', 'INSERT'), 'direct schedule writes are denied');
select is((select count(*)::integer from public.availability_rules where counselor_id = '44444444-4444-4444-8444-444444444444'), 0, 'customer cannot read private weekly hours');
reset role;
select is((select count(*)::integer from public.calculate_availability_slots('44444444-4444-4444-8444-444444444444', '2031-01-01 03:30+00') where start_at < '2031-01-02 00:00+00'), 2, 'overlapping block removes the 11am slot including its buffer');
select is((select min(start_at) from public.calculate_availability_slots('44444444-4444-4444-8444-444444444444', '2031-01-01 03:30+00')), '2031-01-01 04:30+00'::timestamptz, 'one-hour notice includes the exact boundary');
select is((select max(start_at) <= '2031-01-11 04:00+00'::timestamptz from public.calculate_availability_slots('44444444-4444-4444-8444-444444444444', '2031-01-01 04:00+00')), true, 'slots never exceed the ten-day window');
select ok(not has_function_privilege('anon', 'public.calculate_availability_slots(uuid,timestamptz)', 'EXECUTE'), 'arbitrary-time calculation is not public');
set local role authenticated;
select set_config('request.jwt.claim.sub', '22222222-2222-4222-8222-222222222222', true);
select lives_ok($$select public.save_availability_exception('44444444-4444-4444-8444-444444444444', null, '2031-01-01', 'opening', false, '11:30', '14:00')$$, 'counselor can add an overlapping opening');
reset role;
select is((select count(*)::integer from public.calculate_availability_slots('44444444-4444-4444-8444-444444444444', '2031-01-01 03:30+00') where start_at < '2031-01-02 00:00+00'), 3, 'overlapping openings merge without overlapping slots');
set local role authenticated;
select lives_ok($$select public.save_availability_exception('44444444-4444-4444-8444-444444444444', null, '2031-01-02', 'opening', false, '15:00', '17:00')$$, 'counselor can add a date-specific opening');
reset role;
select is((select count(*)::integer from public.calculate_availability_slots('44444444-4444-4444-8444-444444444444', '2031-01-01 03:30+00') where (start_at at time zone 'Asia/Kolkata')::date = '2031-01-02'), 2, 'extra opening generates two slots');
set local role authenticated;
select lives_ok($$select public.save_availability_exception('44444444-4444-4444-8444-444444444444', null, '2031-01-02', 'blocked', true, null, null)$$, 'counselor can block an entire date');
reset role;
select is((select count(*)::integer from public.calculate_availability_slots('44444444-4444-4444-8444-444444444444', '2031-01-01 03:30+00') where (start_at at time zone 'Asia/Kolkata')::date = '2031-01-02'), 0, 'all-day block overrides extra opening');
set local role authenticated;
select set_config('request.jwt.claim.sub', '11111111-1111-4111-8111-111111111111', true);
select lives_ok($$select public.set_availability_settings(30, 15, 60, 10)$$, 'admin can change session and buffer');
reset role;
select is((select end_at - start_at from public.calculate_availability_slots('44444444-4444-4444-8444-444444444444', '2031-01-01 03:30+00') limit 1), interval '30 minutes', 'configured session length changes public slot duration');
select ok((select count(*) > 0 from public.availability_audit_events where actor_user_id = '22222222-2222-4222-8222-222222222222'), 'schedule changes are audited');
set local role authenticated;
select lives_ok($$select public.save_availability_exception('44444444-4444-4444-8444-444444444444', null, (now() at time zone 'Asia/Kolkata')::date + 2, 'opening', false, '10:00', '17:00')$$, 'admin can add another counselor opening');
set local role anon;
select ok((select count(*) > 0 from public.get_public_availability('44444444-4444-4444-8444-444444444444')), 'published counselor slots are public');
set local role authenticated;
update public.counselors set published = false where id = '44444444-4444-4444-8444-444444444444';
set local role anon;
select is((select count(*)::integer from public.get_public_availability('44444444-4444-4444-8444-444444444444')), 0, 'unpublished counselor slots are hidden');
set local role authenticated;
update public.counselors set published = true where id = '44444444-4444-4444-8444-444444444444';
reset role;
update public.profiles set role = 'customer' where id = '22222222-2222-4222-8222-222222222222';
set local role anon;
select is((select count(*)::integer from public.get_public_availability('44444444-4444-4444-8444-444444444444')), 0, 'revoked counselor slots are hidden');
set local role authenticated;
select set_config('request.jwt.claim.sub', '22222222-2222-4222-8222-222222222222', true);
select throws_ok($$select public.save_availability_rule('44444444-4444-4444-8444-444444444444', null, 3, '10:00', '13:00')$$, '42501', 'Not authorized', 'revoked counselor cannot edit schedule');
reset role;
update public.profiles set role = 'counselor' where id = '33333333-3333-4333-8333-333333333333';
set local role authenticated;
select set_config('request.jwt.claim.sub', '33333333-3333-4333-8333-333333333333', true);
select throws_ok($$select public.save_availability_rule('44444444-4444-4444-8444-444444444444', null, 3, '10:00', '13:00')$$, '42501', 'Not authorized', 'another counselor cannot edit this schedule');
select is((select count(*)::integer from public.availability_exceptions where counselor_id = '44444444-4444-4444-8444-444444444444'), 0, 'another counselor cannot read private exceptions');
select set_config('request.jwt.claim.sub', '11111111-1111-4111-8111-111111111111', true);
select throws_ok($$select public.save_availability_rule('44444444-4444-4444-8444-444444444444', null, 3, '13:00', '10:00')$$, '23514', null, 'end time must follow start time');
select throws_ok($$select public.set_availability_settings(45, 15, 2880, 1)$$, '23514', null, 'minimum notice must fit the booking window');
set local role anon;
select ok(not has_table_privilege('anon', 'public.availability_rules', 'SELECT'), 'anonymous users cannot read private weekly hours');
select is((select session_minutes from public.public_session_settings), 30, 'public can read the updated session duration without accessing schedules');
select * from finish();
rollback;